package com.rikkeibank.notification.service;import com.rikkeibank.common.events.TransferEvent;import com.rikkeibank.notification.domain.Notification;import com.rikkeibank.notification.repo.NotificationRepository;import org.slf4j.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TransferEventConsumer{private static final Logger log=LoggerFactory.getLogger(TransferEventConsumer.class);private final NotificationRepository repo;public TransferEventConsumer(NotificationRepository r){repo=r;}@KafkaListener(topics="bank.transfer.events",groupId="notification-service")@Transactional public void consume(TransferEvent e){if(!e.status().equals("COMPLETED")&&!e.status().equals("COMPENSATED")&&!e.status().equals("FAILED"))return;if(repo.existsByTransactionIdAndEventStatus(e.transactionId(),e.status()))return;String message=switch(e.status()){case"COMPLETED"->"Transfer "+e.transactionId()+" completed: "+e.amount();case"COMPENSATED"->"Transfer "+e.transactionId()+" failed and the debit was refunded";default->"Transfer "+e.transactionId()+" failed";};repo.save(new Notification(e.customerId(),e.transactionId(),e.status(),message));log.info("Notification persisted for transfer {} status {}",e.transactionId(),e.status());}}

